/**
 * One-time migration: adds "price" and "stock" to the "shopItem" content
 * type, and moves "itemId" to the end of the form.
 *
 * - price: in dollars, e.g. 4.5 for $4.50. Required, can't be negative.
 * - stock: units on hand. Required whole number, can't be negative.
 * - itemId: now generated by the API when an item is created (the admin
 *   panel shows it read-only), so it no longer belongs at the top of the
 *   form, and moving it keeps it out of the admin table's columns.
 *
 * Both new fields are required, which is safe while no shop items exist.
 * The script refuses to run once any do, since existing items would then
 * fail validation on their next edit.
 *
 * Safe to re-run: fields that already exist are left alone.
 *
 * Requires CONTENTFUL_CMA_TOKEN in .env.local (same as setup-contentful.js).
 *
 * Usage: node scripts/add-shop-price-stock.js
 */

require('dotenv').config({ path: '.env.local' });
const contentfulManagement = require('contentful-management');

const SPACE_ID = process.env.REACT_APP_CONTENTFUL_SPACE_ID;
const ENVIRONMENT_ID = process.env.REACT_APP_CONTENTFUL_ENVIRONMENT || 'master';
const CMA_TOKEN = process.env.CONTENTFUL_CMA_TOKEN;

if (!SPACE_ID || !CMA_TOKEN) {
  console.error('Missing REACT_APP_CONTENTFUL_SPACE_ID or CONTENTFUL_CMA_TOKEN in .env.local');
  process.exit(1);
}

const NEW_FIELDS = [
  {
    id: 'price',
    name: 'Price',
    type: 'Number',
    required: true,
    localized: false,
    validations: [{ range: { min: 0 }, message: "Price can't be negative" }],
  },
  {
    id: 'stock',
    name: 'Stock',
    type: 'Integer',
    required: true,
    localized: false,
    validations: [{ range: { min: 0 }, message: "Stock can't be negative" }],
  },
];

// Price and stock go right after "category", so the admin table's columns
// (the first few non-name fields) read Category, Price, Stock.
const INSERT_AFTER = 'category';

async function main() {
  const client = contentfulManagement.createClient({ accessToken: CMA_TOKEN }, { type: 'plain' });
  const params = { spaceId: SPACE_ID, environmentId: ENVIRONMENT_ID, contentTypeId: 'shopItem' };

  const contentType = await client.contentType.get(params);
  const existingIds = new Set(contentType.fields.map((f) => f.id));
  const toAdd = NEW_FIELDS.filter((f) => !existingIds.has(f.id));

  const itemIdAt = contentType.fields.findIndex((f) => f.id === 'itemId');
  const moveItemId = itemIdAt !== -1 && itemIdAt !== contentType.fields.length - 1;

  if (!toAdd.length && !moveItemId) {
    console.log(`"shopItem" in "${ENVIRONMENT_ID}" already up to date — nothing to do.`);
    return;
  }

  if (toAdd.length) {
    const existing = await client.entry.getMany({
      spaceId: SPACE_ID,
      environmentId: ENVIRONMENT_ID,
      query: { content_type: 'shopItem', limit: 1 },
    });
    if (existing.total) {
      console.error(
        `"${ENVIRONMENT_ID}" already has ${existing.total} shop item(s) - adding required fields would leave them invalid. Aborting.`
      );
      process.exit(1);
    }
  }

  if (moveItemId) contentType.fields.push(...contentType.fields.splice(itemIdAt, 1));
  const insertAt = contentType.fields.findIndex((f) => f.id === INSERT_AFTER) + 1;
  contentType.fields.splice(insertAt, 0, ...toAdd);

  console.log(
    `"${ENVIRONMENT_ID}": adding fields: ${toAdd.map((f) => f.id).join(', ') || '(none)'}${moveItemId ? '; moving itemId to the end' : ''}`
  );
  const updated = await client.contentType.update(params, contentType);
  await client.contentType.publish(params, updated);

  console.log(`Done — "shopItem" updated and published. Field order: ${updated.fields.map((f) => f.id).join(', ')}`);
}

main().catch((err) => {
  console.error('Migration failed:', err.message || err);
  process.exit(1);
});
